'use strict';
const query=new URLSearchParams(location.search), capture=query.get('capture')==='1';
const meta=globalThis.PROTOTYPE_SCREENS;
const A={screen:query.get('screen')||'K-01',state:query.get('state')||'default',cart:[{id:'classic',qty:1},{id:'fries',qty:1}],service:'dine_in',qty:1,verified:false,category:'Бургеры',toast:'',modal:null,values:{},bonus:300,cash:200,roleMode:'MVP'};
const products=[{id:'classic',name:'Классический бургер',price:300,weight:230,kind:'burger'},{id:'cheese',name:'Чизбургер',price:340,weight:245,kind:'burger'},{id:'double',name:'Двойной бургер',price:420,weight:320,kind:'burger'},{id:'chicken',name:'Куриный бургер',price:290,weight:220,kind:'burger'},{id:'fish',name:'Рыбный бургер',price:310,weight:225,kind:'burger'},{id:'veggie',name:'Овощной бургер',price:280,weight:215,kind:'burger'},{id:'fries',name:'Картофель фри',price:120,weight:110,kind:'fries'},{id:'pie',name:'Пирожок с вишней',price:110,weight:80,kind:'pie'},{id:'drink',name:'Лимонад',price:100,weight:400,kind:'drink'},{id:'combo',name:'Комбо с бургером',price:540,weight:640,kind:'burger'}];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n)+' ₽';
const dishWord=n=>(n%100>=11&&n%100<=14)?'блюд':n%10===1?'блюдо':(n%10>=2&&n%10<=4)?'блюда':'блюд';
const pBy=id=>products.find(p=>p.id===id)||products[0];
function total(changed=false){const base=A.cart.reduce((s,l)=>s+(pBy(l.id).price+(changed&&l.id==='classic'?20:0))*l.qty,0);return {base,discount:Math.round(base*10)/100,amount:Math.round(base*90)/100};}
function btn(label,action,kind='',disabled=false,extra=''){return `<button type="button" class="btn ${kind}" data-action="${e(action)}" ${disabled?'disabled':''} ${extra}>${label}</button>`;}
function go(label,id,kind=''){return btn(label,'go:'+id,kind);}
function field(label,name,value='',type='text',hint='',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" name="${e(name)}" value="${e(A.values[name]??value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;}
function select(label,name,options,current=''){return `<label class="field"><span>${label}</span><select name="${e(name)}">${options.map(v=>`<option ${v===(A.values[name]??current)?'selected':''}>${e(v)}</option>`).join('')}</select></label>`;}
function notice(text,kind=''){return `<div class="notice ${kind}">${text}</div>`;}
function pill(text,kind=''){return `<span class="pill ${kind}">${text}</span>`;}
function food(kind='burger'){const base='<svg viewBox="0 0 160 120" aria-hidden="true" fill="none" stroke="#6c8293" stroke-width="3" stroke-linejoin="round">';if(kind==='fries')return base+'<path d="M43 48 38 12h16l5 36M65 47V7h16v40M87 47l6-33h16l-6 35M110 48l10-29h14l-9 34" fill="#f6f8fa"/><path d="m30 46 17 63h68l17-63Z" fill="#dae5ed"/><path d="M64 77h35"/></svg>';if(kind==='drink')return base+'<path d="m56 23 8 87h43l9-87Z" fill="#dce6ee"/><path d="M51 23h70M80 23 92 6h21M68 66h33"/></svg>';if(kind==='pie')return base+'<path d="M25 67c0-26 20-45 55-45s55 19 55 45c0 15-19 31-55 31S25 82 25 67Z" fill="#e1e8ed"/><path d="m58 44 8 22m16-25 8 22m16-19 8 22M37 74h86"/></svg>';return base+'<path d="M25 55c2-25 22-39 55-39s53 14 55 39Z" fill="#dfe8ee"/><path d="m25 64 17 6 17-6 20 6 20-6 20 6 16-6M27 79h106"/><rect x="25" y="85" width="110" height="20" rx="10" fill="#dfe8ee"/><path d="m58 31 6 3m18-9 5 4m18 4 5-1"/></svg>';}
function icon(kind='wait'){return `<div class="status-icon ${kind==='ok'?'ok':kind==='error'?'error':kind==='warn'?'warn':''}">${kind==='ok'?'✓':kind==='error'?'×':kind==='warn'?'!':'···'}</div>`;}
function brand(){return '<div class="brand"><span class="brand-mark">Р</span>РОБОТ И ТОЧКА</div>';}
function help(){A.modal='help';render();}
function kiosk(body,foot=''){return `<section class="kiosk"><header class="kiosk-head">${brand()}${btn('Как получить помощь','help','ghost')}</header><div class="kiosk-body">${body}</div>${foot?`<footer class="kiosk-foot">${foot}</footer>`:''}</section>`;}
function cartDock(){const t=total();return `<div class="row between"><div><div class="total-label">В корзине ${A.cart.reduce((s,l)=>s+l.qty,0)} ${dishWord(A.cart.reduce((s,l)=>s+l.qty,0))}</div><div class="total">${money(t.base)}</div></div>${go('Посмотреть заказ →','K-03','primary')}</div><div class="actions">${btn('Начать заново','reset','')}${go('Проверить заказ','K-03','primary')}</div>`;}
function qty(id,value){return `<div class="qty">${btn('−','minus:'+id,'',value<=1)}<span>${value}</span>${btn('+','plus:'+id)}</div>`;}
function productCard(p){return `<article class="product-card"><div class="product-image" data-action="dish:${p.id}">${food(p.kind)}${p.id==='classic'?'<span class="product-badge">Бизнес-ланч −10%</span>':''}</div><div class="product-info"><div class="product-name">${p.name}</div><div class="product-bottom"><span>${money(p.price)}</span><button class="plus-btn" type="button" aria-label="Добавить ${p.name}" data-action="add:${p.id}">+</button></div></div></article>`;}
function catalog(){const categories=['Бургеры','Напитки','Гарниры','Комбо','Десерты'];let list=A.category==='Бургеры'?products.slice(0,6):A.category==='Напитки'?[pBy('drink')]:A.category==='Гарниры'?[pBy('fries')]:A.category==='Комбо'?[pBy('combo')]:[pBy('pie')];let content=A.state==='empty'?empty('Нет доступных блюд','Подойдите к менеджеру — он поможет с выбором.'):A.state==='loading'?`<div class="product-grid">${Array.from({length:6},()=>'<div class="product-card"><div class="product-image"></div><div class="product-info"><div class="skeleton"></div><div class="skeleton short"></div></div></div>').join('')}</div>`:A.state==='error'?empty('Не удалось загрузить меню','Сейчас нельзя начать оплату. Обратитесь к менеджеру.','error'):`<div class="product-grid">${list.map(productCard).join('')}</div>`;
return kiosk(`<div class="catalog-layout"><aside class="categories">${categories.map((c,i)=>`<button class="category ${A.category===c?'active':''}" data-action="category:${c}"><span class="category-symbol">${['◉','▱','▥','▧','◇'][i]}</span>${c}</button>`).join('')}</aside><main class="catalog-main"><h1>${A.category}</h1><div class="subheading">Выберите блюдо или откройте карточку</div>${content}</main></div>`,cartDock());}
function dish(){const p=pBy(A.values.dish||'classic');const composition={classic:'Булочка, говяжья котлета, томаты, салат, маринованные огурцы, фирменный соус.',cheese:'Булочка, говяжья котлета, сыр, томаты, огурцы, соус.',double:'Булочка, две говяжьи котлеты, сыр, салат, томаты, соус.',chicken:'Булочка, куриная котлета, салат, томаты, соус.',fish:'Булочка, рыбное филе, салат, огурцы, соус.',veggie:'Булочка, овощная котлета, салат, томаты, соус.',fries:'Картофель в панировке, растительное масло, соль.',pie:'Пшеничное тесто, вишневая начинка, сливочное масло.',drink:'Вода, лимонный сок, сахар.',combo:'Классический бургер, картофель фри, лимонад.'}[p.id];const allergens={fish:'Глютен, рыба, молоко, горчица.',fries:'Глютен.',pie:'Глютен, молоко.',drink:'Не заявлены.'}[p.id]||'Глютен, молоко, горчица.';return kiosk(`<div class="kiosk-pad">${go('← Вернуться в меню','K-01','ghost')}<div class="dish-hero">${food(p.kind)}</div><div class="dish-summary"><div><h1>${p.name}</h1><span class="muted">${p.weight} г</span></div><div class="price">${money(p.price)}</div></div><h3>Состав</h3><p class="muted" style="font-size:22px;line-height:1.6">${composition}</p><div class="notice info" style="margin:22px 0">Аллергены: ${allergens}</div><div class="row between" style="margin:24px 0 30px"><h3 style="margin:0">Количество</h3>${qty('dish',A.qty)}</div>${p.kind==='burger'&&p.id!=='combo'?`<h2>Дополнить заказ?</h2><div class="upsell">${['fries','pie'].map(id=>`<div class="upsell-card">${food(pBy(id).kind)}<label><input type="checkbox" name="extra-${id}"><span>${pBy(id).name}<br><strong>${money(pBy(id).price)}</strong></span></label></div>`).join('')}</div>`:''}${A.state==='unavailable'?'<div style="margin-top:22px">'+notice('Это блюдо больше недоступно. Выберите другое в меню.','error')+'</div>':''}</div>`,`${btn('Добавить в корзину · '+money(p.price*A.qty),'addDish','primary wide',A.state==='unavailable')}`);}
function empty(title,detail,kind='wait'){return `<div class="empty">${icon(kind)}<h2>${title}</h2><p>${detail}</p></div>`;}
function cartLines(changed=false,unavailable=false){return A.cart.map(l=>{const p=pBy(l.id);return `<div class="cart-line" ${unavailable&&l.id==='fries'?'style="background:#fff3f3"':''}><div class="cart-thumb">${food(p.kind)}</div><div class="grow"><div class="name">${p.name}</div><div class="muted" style="font-size:17px">${unavailable&&l.id==='fries'?'Больше недоступно':money(p.price+(changed&&l.id==='classic'?20:0))+' за порцию'}</div></div>${qty(l.id,l.qty)}<div class="price">${money((p.price+(changed&&l.id==='classic'?20:0))*l.qty)}</div><button class="trash" aria-label="Удалить ${p.name}" data-action="remove:${l.id}">×</button></div>`;}).join('');}
function cart(){const changed=A.state==='changed',unavailable=A.state==='unavailable',isEmpty=A.state==='empty'||!A.cart.length;const t=total(changed),confirmed=['confirmed','changed'].includes(A.state);return kiosk(`<div class="kiosk-pad"><div class="row between" style="margin-bottom:25px"><h1 style="margin:0">Ваш заказ</h1>${btn(A.service==='takeaway'?'С собой ▾':'В зале ▾','service','small')}</div>${isEmpty?empty('Корзина пуста','Добавьте блюда из меню, чтобы продолжить.'):cartLines(changed,unavailable)}${!isEmpty?`<div class="row between" style="margin:22px 0">${go('← Добавить еще блюда','K-01','ghost')}<span class="muted">${A.service==='takeaway'?'Упакуем с собой':'Подача в зале'}</span></div>${changed?notice('Цена бургера изменилась: 300 ₽ → 320 ₽. Проверьте новый итог перед оплатой.'):unavailable?notice('Картофель фри закончился. Удалите его или вернитесь в меню.','error'):notice(confirmed?'Состав и сумма проверены. Подтвердите оплату.':'Проверьте состав и тип обслуживания.','info')}<div class="receipt-summary"><div class="sum-row"><span>Стоимость блюд</span><span>${money(t.base)}</span></div><div class="sum-row discount"><span>Бизнес-ланч · скидка 10%</span><span>−${money(t.discount)}</span></div><div class="sum-row strong"><span>Итого к оплате</span><span>${money(t.amount)}</span></div></div>`:''}</div>`,isEmpty?go('Вернуться в меню','K-01','primary wide'):`<div class="row between"><div><div class="total-label">К оплате</div><div class="total">${money(t.amount)}</div></div>${confirmed?btn('Подтверждаю '+money(t.amount)+', оплатить','pay','primary'):btn('Проверить заказ','prepare','primary',unavailable)}</div>`);}
function terminal(){return '<div class="terminal"><div class="terminal-display">Оплата</div><div class="terminal-keys">'+Array.from({length:12},()=>'<i></i>').join('')+'</div></div>';}
function payment(){let unknown=A.state==='unknown',declined=A.state==='declined';return kiosk(`<div class="payment-center">${declined?icon('error'):unknown?icon('wait'):terminal()}<h1>${declined?'Банк отказал в оплате':unknown?'Проверяем оплату':'Оплатите банковской картой'}</h1><div class="big-amount">${money(dueAmount())}</div><p>${declined?'Деньги не списаны. Вернитесь к заказу, чтобы проверить его и попробовать оплатить снова.':unknown?'Результат пока не получен. Не оплачивайте заказ повторно и дождитесь проверки.':'Следуйте инструкции на платежном терминале.'}</p>${unknown?`<div style="width:100%;margin-top:35px">${notice('Если проверка затянется, менеджер поможет уточнить результат.','info')}</div>`:''}</div>`,declined?go('Вернуться к заказу','K-03','primary wide'):'<div class="row between"><span class="muted" style="font-size:19px">'+(unknown?'Проверка продолжается':'Не убирайте карту до сообщения терминала')+'</span>'+btn('Как получить помощь','help','ghost')+'</div>');}
function paid(){const printing=A.state==='printing';return kiosk(`<div class="payment-center" style="padding-top:45px">${icon('ok')}<h1>Заказ оплачен</h1><p style="margin:4px 0 5px">Номер вашего заказа</p><div class="order-number">042</div><p>Оплачено ${money(dueAmount())}<br>Следите за номером на табло.</p><div class="doc-pair"><div class="doc-card"><h3>Фискальный чек</h3><p>${printing?'··· Печатается':'✓ Напечатан'}</p></div><div class="doc-card"><h3>Талон для получения</h3><p>${printing?'··· Печатается':'✓ Напечатан'}</p></div></div><div style="margin-top:30px;width:100%">${notice(printing?'Дождитесь печати документов.':'Заберите чек и талон из принтера. Талон понадобится, чтобы открыть ячейку.','info')}</div></div>`,btn('Завершить','reset','primary wide',printing));}
function documentHelp(){const accepted=A.state==='accepted';return kiosk(`<div class="payment-center">${icon('warn')}<h1>Оплата прошла.<br>Нужна помощь с талоном</h1><div class="order-number" style="font-size:82px">042</div><p>Оплачено ${money(dueAmount())}.<br>Повторно оплачивать заказ не нужно.</p><div class="panel" style="width:100%;text-align:left;margin:22px 0"><h2>${accepted?'Менеджер принял обращение':'Обратитесь к менеджеру в зале'}</h2><p style="font-size:21px;margin:0">${accepted?'Покупка сохранена у менеджера. Он поможет получить талон или решить проблему.':'Сообщите номер заказа и покажите подтверждение оплаты. Менеджер проверит покупку и поможет получить талон.'}</p></div><span class="pill ${accepted?'green':'amber'}">${accepted?'Обращение в работе':'Ожидание помощи'}</span></div>`,btn('Завершить','reset','primary wide',!accepted));}
function stopped(){return kiosk(`<div class="payment-center" style="padding-top:110px">${icon('warn')}<h1>Сейчас нельзя оформить<br>новый заказ</h1><p>${A.state==='technical'?'Временно нет связи с необходимым оборудованием. Мы восстанавливаем работу.':'Новые продажи приостановлены на время технического перерыва.'}</p><div class="panel" style="text-align:left;width:100%;margin-top:40px"><h2>Уже оплатили заказ?</h2><p style="font-size:22px;margin-bottom:0">Ожидайте готовности на табло. Если нужна помощь с оплатой или получением, обратитесь к менеджеру.</p></div></div>`);}
function board(){const noData=['error','loading'].includes(A.state);return `<section class="board"><header class="board-head">${brand()}<h1>Готовность заказов</h1></header>${noData?empty(A.state==='loading'?'Загружаем данные':'Данные временно недоступны',A.state==='loading'?'Информация появится автоматически.':'Если вы уже оплатили заказ, обратитесь к менеджеру.',A.state==='loading'?'wait':'warn'):`<div class="board-cols"><section class="board-col"><h2>Готовится</h2>${A.state==='empty'?empty('Заказов пока нет','Здесь появятся номера принятых заказов.'):'<div class="preparing-numbers"><span>041</span><span>043</span><span>045</span><span>047</span></div>'}</section><section class="board-col ready"><h2>Готов</h2>${A.state==='empty'?empty('Готовых заказов нет','Дождитесь появления своего номера.'):'<div class="ready-order"><strong>042</strong><span>Ячейка 7 →</span></div><div class="ready-order"><strong>044</strong><span>Ячейка 2 →</span></div>'}</section></div>`}<footer class="board-foot"><span>Для получения используйте талон.</span><span>Номер исчез до получения?<br>Обратитесь к менеджеру.</span></footer></section>`;}
function pickup(){const d={default:['Поднесите талон к сканеру','Код на талоне откроет назначенную вам ячейку. Публичный номер заказа для открытия не подходит.','wait'],open:['Ячейка 7 открыта','Заберите заказ и закройте дверцу. Не оставляйте внутри часть заказа.','ok'],partial:['В ячейке осталась часть заказа','Заберите остаток тем же талоном до окончания исходного срока получения.','warn'],issued:['Заказ получен. Спасибо!','Дверца закрыта. Заказ полностью забран. Приятного аппетита!','ok'],expired:['Срок получения истек','Открыть ячейку этим талоном больше нельзя. Обратитесь к менеджеру.','warn'],invalid:['Талон не подходит','Проверьте талон и повторите считывание. Если нужна помощь, обратитесь к менеджеру.','error'],fault:['Ячейка временно недоступна','Не пытайтесь открыть дверцу самостоятельно. Обратитесь к менеджеру.','warn']}[A.state]||null;const [title,detail,kind]=d||['Поднесите талон к сканеру','Используйте талон вашего заказа.','wait'];return `<section class="board"><header class="board-head">${brand()}<h1>Получение заказа</h1></header><div class="pickup-layout"><section class="pickup-message">${icon(kind)}<h1>${title}</h1><p>${detail}</p>${['open','partial'].includes(A.state)?'<div class="notice info" style="font-size:22px;margin-top:32px">Заказ 042 · ячейка 7</div>':''}</section><section><div class="pickup-grid">${Array.from({length:8},(_,i)=>`<div class="locker ${i===6&&['open','partial'].includes(A.state)?'selected':''}">${i+1}</div>`).join('')}</div><div class="scanner"><span class="scan-symbol">▣</span>Считыватель талона</div></section></div><footer class="board-foot"><span>Заберите заказ в течение 10 минут<br>после первого появления в «Готов».</span><span>Проблема с получением?<br>Обратитесь к менеджеру.</span></footer></section>`;}
const roleNames={manager:'Анна К. · менеджер гостеприимства',hall:'Сотрудник зала',assortment:'Менеджер по ассортименту',technology:'Технолог',production:'Сотрудник производства',analyst:'Аналитик ресторана'};
function work(body,section='Проблемы',role='manager',r1=false){const links=role==='hall'?[['Ячейки','S-03']]:role==='assortment'?[['Меню следующего дня','R-05'],['Акции и комбо','R-05:promotion']]:role==='technology'?[['Технологические карты','R-06']]:role==='production'?[['Состояние комплекса','R-07']]:role==='analyst'?[['Продажи и возвраты','R-08'],['Передача в 1С','R-08:exportPending']]:r1?[['Заказы','R-04'],['Уведомления','R-04:notifications'],['Ячейки','S-03'],['Продажи','S-04']]:[['Проблемы','S-01'],['Найти заказ','S-01'],['Ячейки','S-03'],['Продажи','S-04']];return `<section class="desktop"><header class="work-head">${brand()}<div class="row"><span class="pill">Москва · ресторан 01</span><div class="employee">${roleNames[role]}<br><span class="muted">16 ноября 2026 · 12:40</span></div></div></header><div class="work-layout"><aside class="work-nav"><div class="nav-heading">Рабочее место</div>${links.map(([t,id])=>`<button class="${section===t?'selected':''}" data-action="go:${id}">${t}</button>`).join('')}<div class="nav-foot">Личная учетная запись<br>${go('Выйти','S-00','small ghost')}</div></aside><main class="work-main">${body}</main></div></section>`;}
function title(name,sub='',right=''){return `<div class="page-title"><div><h1>${name}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;}
function login(){return `<section class="desktop"><div class="login-stage"><div class="login-card">${brand()}<h1>Вход сотрудника</h1><p>Используйте личную учетную запись для доступа к рабочему месту.</p>${A.state==='error'?notice('Неверный логин или пароль. Проверьте введенные данные.','error'):''}<div style="margin-top:24px">${field('Логин','login','','text','', 'autocomplete="off" required')}${field('Пароль','password','','password','','autocomplete="off" required')}${btn('Войти','login','primary')}</div><div class="divider"></div><span class="tiny muted">Если нет доступа, обратитесь к ответственному сотруднику ресторана.</span></div></div></section>`;}
function searchMvp(){return `<section class="panel" style="margin-bottom:24px"><h2>Найти заказ</h2><div class="filter-row">${select('Ресторан','restaurant',['Москва · ресторан 01'])}${field('Торговый день','day','2026-11-16','date')}${field('Номер заказа','orderNumber','042')}${btn('Найти','findMvp','primary')}</div></section>`;}
function problems(){let rows=A.state==='empty'?'<tr><td colspan="5"><div class="empty"><h2>Новых проблем нет</h2><p>Новые обращения появятся в этом списке.</p></div></td></tr>':A.state==='loading'?'<tr><td colspan="5"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton short"></div></td></tr>':A.state==='error'?'<tr><td colspan="5">'+notice('Не удалось обновить проблемы. Принятие обращений пока недоступно.','error')+'</td></tr>':`<tr><td><strong>042</strong><div class="tiny muted">Киоск 2</div></td><td>Талон не напечатан<div class="tiny muted">Оплата подтверждена</div></td><td>12:39:15<div class="tiny muted">Доставлено 45 с назад</div></td><td>${pill(A.state==='accepted'?'Принято вами':'Новая',A.state==='accepted'?'green':'amber')}</td><td>${btn(A.state==='accepted'?'Открыть':'Принять','acceptProblem','small primary')}</td></tr><tr><td><strong>Без номера</strong><div class="tiny muted">Киоск 3</div></td><td>Проверка оплаты<div class="tiny muted">Результат не получен</div></td><td>12:39:42</td><td>${pill('Новая','amber')}</td><td>${go('Открыть покупку','S-02:paymentUnknown','small')}</td></tr><tr><td><strong>Ячейка 3</strong></td><td>Неисправность датчика<div class="tiny muted">Требуется сотрудник зала</div></td><td>12:38:07</td><td>${pill('В работе')}</td><td>${go('К ячейкам','S-03','small')}</td></tr>`;return work(title('Проблемы и помощь гостям','Новые обращения выделены до принятия ответственным сотрудником.',pill('Есть непринятые обращения','amber'))+searchMvp()+`<section class="table-card"><div class="table-title"><h2>Проблемы ресторана</h2><span class="tiny muted">Обновлено 12:40:00</span></div><table><thead><tr><th>Заказ / ячейка</th><th>Причина</th><th>Уведомление</th><th>Состояние</th><th>Действие</th></tr></thead><tbody>${rows}</tbody></table></section>`);}
function unknownPurchase(){return work(title('Покупка · киоск 3','16 ноября · 12:38 · Публичный номер еще не присвоен',go('← К проблемам','S-01','small'))+notice('Результат оплаты неизвестен. Повторная оплата и отмена покупки до сверки недоступны.','info')+`<div class="two-col" style="margin-top:24px"><section class="panel"><h2>Сохраненный состав</h2><table><thead><tr><th>Блюдо</th><th>Количество</th><th>Сумма</th></tr></thead><tbody><tr><td>Классический бургер</td><td>1</td><td>300 ₽</td></tr><tr><td>Картофель фри</td><td>1</td><td>120 ₽</td></tr></tbody></table><div class="sum-row"><span>Скидка бизнес-ланча</span><span>−42 ₽</span></div><div class="row between"><strong>Сумма попытки оплаты</strong><strong>378 ₽</strong></div></section><section class="panel"><h2>Проверка оплаты</h2><ul class="check-list"><li>Способ <strong>Банковская карта</strong></li><li>Результат ${pill('На проверке','amber')}</li><li>Резерв <strong>Удерживается</strong></li><li>Чек и талон <strong>Не сформированы</strong></li></ul><p class="smalltext muted">Сверка исходной попытки продолжается. Сброс киоска не отменяет платеж. Номер заказа появится после подтвержденной оплаты.</p></section></div>`);}
function orderDetail(r1=false){if(!r1&&A.state==='paymentUnknown')return unknownPurchase();const number=r1?(A.selectedOrder||'042'):'042';const phase=r1?({"042":'paid',"041":'preparing',"040":'ready',"039":'issued',"038":'cancelled'}[number]||'paid'):'problem';const phaseLabel={paid:'Оплачен, ожидает кухни',preparing:'Готовится',ready:'Готов',issued:'Выдан',cancelled:'Отменен'}[phase];const pending=(['cancelled','refund','refundPending','refundConfirmed'].includes(A.state)||phase==='cancelled'),confirmed=A.state==='refundConfirmed',verified=A.verified||['verified','reprinted'].includes(A.state),reprinted=['reprinted','resolved'].includes(A.state);const body=title('Заказ '+number,`16 ноября · 12:36 · Киоск 2 · В зале`,go('← '+(r1?'К заказам':'К проблемам'),r1?'R-04':'S-01','small'))+`<div class="row" style="margin-bottom:22px">${pill(pending?'Отменен':A.state==='resolved'?'Готовится':r1?phaseLabel:'Проблема',pending?'':'amber')}${pill('Оплата подтверждена','green')}${pending?pill(confirmed?'Возврат подтвержден':(['cancelled','refund'].includes(A.state)||phase==='cancelled')?'Возврат требуется':'Возврат проверяется',confirmed?'green':'amber'):''}</div><div class="two-col"><div class="stack"><section class="panel"><h2>Состав заказа</h2><table><thead><tr><th>Блюдо</th><th>Количество</th><th>Сумма</th></tr></thead><tbody><tr><td>Классический бургер</td><td>1</td><td>300 ₽</td></tr><tr><td>Картофель фри</td><td>1</td><td>120 ₽</td></tr></tbody></table><div class="sum-row smalltext"><span>Скидка бизнес-ланча</span><span>−42 ₽</span></div><div class="row between"><strong>Оплачено</strong><strong style="font-size:25px">378 ₽</strong></div></section><section class="panel"><h2>Оплата и возврат</h2><dl class="info-grid"><div><dt>Способ оплаты</dt><dd>Банковская карта</dd></div><div><dt>Время подтверждения</dt><dd>12:37:08</dd></div><div><dt>Оплата</dt><dd>378 ₽ · подтверждена</dd></div><div><dt>Возврат</dt><dd>${pending?(confirmed?'378 ₽ · подтвержден':['cancelled','refund'].includes(A.state)?'378 ₽ · требуется':'378 ₽ · проверяется'):'Не оформлялся'}</dd></div></dl>${pending?notice(confirmed?'Деньги возвращены. Чек возврата подтвержден.':['cancelled','refund'].includes(A.state)?'Выполнение прекращено. Требуется полный возврат 378 ₽.':'Выполнение заказа прекращено. Возврат денег пока не подтвержден.',confirmed?'success':'info'):notice(r1?(phase==='paid'?'До начала приготовления заказ можно отменить по просьбе гостя.':'Отмена после начала приготовления доступна только при невозможности выполнения или подтвержденной проблеме.'):'Возврат проводится через внешний платежный сервис. Укажите идентификатор для проверки результата.','info')}</section></div><div class="stack"><section class="panel"><h2>Документы</h2><ul class="check-list"><li>Фискальный чек ${pill('Подтвержден','green')}</li><li>Талон ${pill(reprinted?'Напечатан':r1?'Напечатан':'Ошибка печати',reprinted||r1?'green':'red')}</li></ul>${!r1?`<p class="smalltext muted">Восстановление талона — после проверки покупки. Новый номер не создается.</p><div class="stack" style="gap:10px">${btn(verified?'Покупка проверена':'Проверить покупку','verify','small',verified)}${btn('Повторить печать талона','reprint','small primary',!verified||pending)}</div>`:''}</section><section class="panel"><h2>Разбор обращения</h2><p class="smalltext"><strong>Ответственная:</strong> Анна К.<br><span class="muted">${r1?'Обращение гостя':'Талон не вышел из принтера киоска 2'}</span></p><div class="stack" style="gap:10px">${r1?btn('Отменить заказ','r1Cancel','small danger',pending||phase!=='paid'):btn('Заказ невозможно выполнить','impossibility','small danger',pending)}${r1?btn('Оформить полный возврат','r1Refund','small primary',!pending||A.state==='refundPending'||confirmed):btn('Указать ID внешнего возврата','externalRefund','small',!pending||A.state==='refundPending'||confirmed)}${btn('Зафиксировать результат','resolve','small',(pending&&!confirmed)||(!r1&&!reprinted&&!confirmed))}</div></section></div></div>`;return work(body,r1?'Заказы':'Проблемы','manager',r1);}
function cells(){const fault=A.state==='fault',checking=A.state==='checking';if(A.state==='empty')return work(title('Обслуживание ячеек','Только задачи уборки и восстановления контроля.')+'<section class="panel">'+empty('Нет задач обслуживания','Проблемные ячейки появятся здесь.')+'</section>','Ячейки','hall');return work(title('Обслуживание ячеек','Закройте дверцу после обслуживания. Ячейка вернется в работу после проверки.')+`<div class="two-col" style="grid-template-columns:1fr 1.25fr"><section><div class="cell-task ${!fault?'active':''}"><div class="row"><span class="cell-id">7</span><div><strong>Срок получения истек</strong><p class="smalltext muted" style="margin:7px 0 0">Нужна уборка остатка заказа</p></div></div><div class="row between" style="margin-top:18px">${pill(checking?'Проверяется':'Ожидает уборки','amber')}${btn('Открыть задачу','cellDefault','small')}</div></div><div class="cell-task ${fault?'active':''}"><div class="row"><span class="cell-id">3</span><div><strong>Датчик неисправен</strong><p class="smalltext muted" style="margin:7px 0 0">Автоматическая выдача заблокирована</p></div></div><div class="row between" style="margin-top:18px">${pill('Проблема','red')}${btn('Открыть задачу','cellFault','small')}</div></div></section><section class="panel"><div class="row between"><h2 style="margin:0">Ячейка ${fault?'3':'7'}</h2>${pill(fault?'Заблокирована':checking?'Контроль':'Уборка',fault?'red':'amber')}</div><div class="divider"></div><ul class="check-list"><li><span>Дверца закрыта</span><span class="check-dot">✓</span></li><li><span>Датчик исправен</span><span class="check-dot ${fault?'bad':''}">${fault?'×':'✓'}</span></li><li><span>Стабильная пустота</span><span class="check-dot ${!checking||fault?'bad':''}">${checking&&!fault?'✓':'—'}</span></li><li><span>Уборка завершена</span><span class="check-dot ${checking?'':'bad'}">${checking?'✓':'—'}</span></li></ul><div style="margin:20px 0">${notice(fault?'Удаление еды не устраняет неисправность датчика. Требуется восстановить контроль.':checking?'Уборка отмечена. Ожидается завершение проверки ячейки.':'Удалите остатки еды, проверьте чистоту и закройте дверцу.','info')}</div><div class="stack">${btn('Принять задачу','cellAccept','small')}${btn(fault?'Зафиксировать обслуживание':'Уборка завершена','cellService','primary',checking)}</div></section></div>`,'Ячейки','hall');}
function sales(){const stopped=['stopped','technical'].includes(A.state),bad=A.state==='technical';const checks=['Доступность блюд и резерв','Сохранение покупки','Оплата картой','Прием задания кухней','Кассовая система','Печать чека и талона'];return work(title('Управление продажами','Режим ресторана и контроль начатых операций.')+`<div class="panel row between" style="margin-bottom:22px;background:${stopped?'#fff7e8':'#eef6f0'}"><div><h2 style="margin:0 0 10px">${stopped?'Новые продажи остановлены':'Продажи разрешены'}</h2><div class="muted">${stopped?'Причина: технический перерыв · Анна К. · 12:40':'Киоски принимают новые заказы'}</div></div>${btn(stopped?'Возобновить продажи':'Остановить продажи',stopped?'resumeSales':'stopSales',stopped?'primary':'danger',bad)}</div><div class="two-col"><section class="panel"><h2>Проверка готовности</h2><ul class="check-list">${checks.map((c,i)=>`<li><span>${c}</span><span class="row"><span class="tiny muted">${bad&&i===5?'Нет подтверждения':'Работает'}</span><span class="check-dot ${bad&&i===5?'bad':''}">${bad&&i===5?'×':'✓'}</span></span></li>`).join('')}</ul></section><div class="stack"><section class="panel"><h2>Начатые операции</h2><ul class="check-list"><li>Платежи на проверке <strong>1</strong></li><li>Заказы в выполнении <strong>4</strong></li><li>Неподтвержденные возвраты <strong>1</strong></li></ul></section>${notice('Оборудование отключать рано. Дождитесь проверки платежей и завершения оплаченных заказов.','info')}<p class="smalltext muted">Остановка новых продаж не прекращает приготовление, выдачу и сверку начатых операций.</p></div></div>`,'Продажи');}
function loyalty(){const register=A.state==='register'||A.values.authMode==='register',code=['code','error'].includes(A.state);return kiosk(`<div class="kiosk-pad"><div style="max-width:680px;margin:30px auto"><h1>${code?'Подтвердите телефон':'Бонусы за ваши заказы'}</h1><p class="muted" style="font-size:22px;margin-bottom:32px">Войдите в программу лояльности или продолжите без регистрации.</p>${!code?`<div class="tabs">${btn('Войти','authLogin',register?'':'selected')}${btn('Зарегистрироваться','authRegister',register?'selected':'')}</div>`:''}<div class="panel" style="padding:30px">${code?`<p style="margin-top:0;font-size:22px">Код отправлен на ${e(A.values.phone||'+7 ••• •••-45-67')}</p>${field('Код из SMS','sms','','text','','autocomplete="off" required')}${A.state==='error'?notice('Код неверный или срок его действия истек.','error'):''}${btn('Подтвердить','authConfirm','primary wide')}<div style="margin-top:20px">${btn('Отправить код повторно','resendCode','ghost small')}</div>`:`${field('Номер телефона','phone','','tel','Например, +7 900 000-00-00','autocomplete="off" placeholder="+7 ___ ___-__-__" required')}${register?`${field('Имя','guestName','','text','','autocomplete="off" required')}${field('Дата рождения','birthDate','','date','','required')}${field('Email — по желанию','email','','email')}`:''}${btn('Получить код','sendCode','primary wide')}`}</div><div style="margin-top:26px">${go('Продолжить без бонусов','K-03','ghost wide')}</div></div></div>`,`<div class="row between"><span class="muted">Ваша корзина сохранена</span><strong>${money(total().amount)}</strong></div>`);}
function bonus(){const no=A.state==='noBonus',missing=A.state==='giftMissing',spent=no?0:A.bonus,amount=1790-spent;return kiosk(`<div class="kiosk-pad"><div class="row between"><h1 style="margin:0">Ваш заказ и бонусы</h1><span class="pill green">Вы вошли</span></div><div style="margin-top:28px"><div class="cart-line"><div class="cart-thumb">${food('burger')}</div><div class="grow"><div class="name">Большое комбо</div><span class="muted">Готовые блюда · 1 набор</span></div><strong>1 700 ₽</strong></div><div class="cart-line"><div class="cart-thumb">${food('drink')}</div><div class="grow"><div class="name">Лимонад</div><span class="muted">400 мл · 1 порция</span></div><strong>100 ₽</strong></div></div><div class="bonus-box"><div class="row between" style="margin-bottom:20px"><h2 style="margin:0">Ваш баланс</h2><strong>${no?'0':'600'} бонусов</strong></div>${field('Списать бонусы','bonus',spent,'number','Можно списать не более 537 бонусов','min="0" max="'+(no?0:537)+'" '+(no?'disabled':''))}<div class="smalltext muted">1 бонус = 1 ₽. Бонусами можно оплатить до 30% суммы после скидок.</div></div><div class="gift">${missing?'Подарочные стаканы закончились. Подтвердите заказ без подарка.':'✓ Подарок к заказу: стакан · 0 ₽<br><span class="smalltext">Добавлен при сумме больше 1 500 ₽ после скидок, до бонусов.</span>'}</div><div class="receipt-summary" style="margin-top:18px"><div class="sum-row"><span>Стоимость блюд</span><span>1 800 ₽</span></div><div class="sum-row discount"><span>Бизнес-ланч на напиток</span><span>−10 ₽</span></div><div class="sum-row"><span>Списание бонусов</span><span>−${money(spent)}</span></div><div class="sum-row strong"><span>К оплате деньгами</span><span>${money(amount)}</span></div><div class="smalltext muted">Будет начислено ${Math.floor(amount*.05)} бонусов после оплаты</div></div></div>`,btn('Подтверждаю '+money(amount)+', к оплате','bonusPay','primary wide'));}
function cash(){const unknown=A.state==='returnUnknown',unavailable=A.state==='unavailable',amount=dueAmount(),inserted=unavailable?0:A.cash;return kiosk(`<div class="payment-center" style="padding-top:55px">${icon(unknown?'wait':unavailable?'warn':'wait')}<h1>${unknown?'Проверяем возврат денег':unavailable?'Наличные сейчас недоступны':'Оплата наличными'}</h1><p>${unknown?'Результат возврата внесенной суммы пока неизвестен. Не начинайте новую оплату. Обратитесь к менеджеру.':unavailable?'Устройство приема денег или выдачи сдачи недоступно. Вернитесь к заказу и выберите оплату картой.':'Внесите деньги в купюроприемник. Дождитесь подтверждения суммы и выдачи сдачи.'}</p>${unknown?`<div class="bill-return" style="width:100%;text-align:left"><div><span class="muted">Сумма к возврату</span><strong>${money(A.cash)}</strong></div><div><span class="muted">Результат</span><strong style="font-size:25px">Проверяется</strong></div></div>`:`<div class="bill-return" style="width:100%;text-align:left"><div><span class="muted">К оплате</span><strong>${money(amount)}</strong></div><div><span class="muted">Внесено</span><strong>${money(inserted)}</strong></div><div><span class="muted">Осталось внести</span><strong>${money(Math.max(0,amount-inserted))}</strong></div><div><span class="muted">Сдача</span><strong>${money(Math.max(0,inserted-amount))}</strong></div></div>`}${unknown?notice('Менеджер поможет проверить возврат. Повторная оплата пока недоступна.','info'):''}</div>`,unknown?btn('Как получить помощь','help','wide'):unavailable?go('Вернуться к заказу','K-03','primary wide'):btn('Отменить и вернуть '+money(A.cash),'cancelCash','wide',A.cash>=amount));}
function fullManager(){if(['detail','cancel','refund','cancelled','refundPending','refundConfirmed'].includes(A.state))return orderDetail(true);const notifications=A.state==='notifications';if(notifications)return work(title('Уведомления','Снятия блюд и технические события ресторана.')+`<section class="table-card"><table><thead><tr><th>Время</th><th>Событие</th><th>Описание</th><th>Связанный заказ</th></tr></thead><tbody><tr><td>12:39</td><td>${pill('Блюдо снято','amber')}</td><td>Рыбный бургер временно недоступен</td><td>—</td></tr><tr><td>12:38</td><td>${pill('Технический сбой','red')}</td><td>Талон не напечатан на киоске 2</td><td>${btn('Открыть 042','r1Detail','small')}</td></tr><tr><td>12:35</td><td>${pill('Технический сбой','amber')}</td><td>Печать недоступна на киоске 4</td><td>—</td></tr></tbody></table></section>`,'Уведомления','manager',true);return work(title('Заказы ресторана','Поиск и разбор обращений за выбранный период.')+`<section class="panel" style="margin-bottom:22px"><div class="filter-row">${field('С','dateFrom','2026-11-16','date')}${field('До','dateTo','2026-11-17','date')}${select('Состояние заказа','orderState',['Все','Готовится','Готов','Проблема','Отменен'])}${select('Оплата','paymentState',['Все','Подтверждена','На проверке','Отказ'])}${btn('Найти','searchOrders','primary')}</div><div class="row" style="margin-top:15px"><label class="field inline" style="max-width:240px"><span>Номер заказа</span><input name="r1number" placeholder="Любой"></label><span class="tiny muted">Ресторан: Москва · ресторан 01</span></div></section><section class="table-card"><div class="table-title"><h2>Найденные заказы</h2><span class="muted smalltext">${A.state==='empty'?'0':'5'} заказов</span></div><table><thead><tr><th>Номер</th><th>Время</th><th>Состояние заказа</th><th>Оплата</th><th>Сумма</th><th></th></tr></thead><tbody>${A.state==='empty'?'<tr><td colspan="6">'+empty('Заказы не найдены','Измените период или условия поиска.')+'</td></tr>':['042','041','040','039','038'].map((n,i)=>`<tr><td><strong>${n}</strong></td><td>12:37</td><td>${pill(['Ожидает кухни','Готовится','Готов','Выдан','Отменен'][i],i===2?'green':i===4?'':'amber')}</td><td>${pill('Подтверждена','green')}</td><td>378 ₽</td><td>${btn('Открыть','r1Detail:'+n,'small')}</td></tr>`).join('')}</tbody></table></section>`,'Заказы','manager',true);}
function menuEditor(){const promotion=A.state==='promotion',combo=A.state==='combo';let editor=promotion?`<h2>Акция «Бизнес-ланч»</h2>${field('Название','promoName','Бизнес-ланч')}<span class="smalltext bold">Дни действия</span><div class="weekday">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((d,i)=>`<label><input type="checkbox" ${i<5?'checked':''}>${d}</label>`).join('')}</div><div class="form-row" style="margin-top:20px">${field('Начало, включительно','startTime','10:00','time')}${field('Окончание, не включая','endTime','16:00','time')}</div>${field('Скидка, %','discount','10','number','','min="0" max="100"')}<div class="notice info">Участвуют обычные блюда без другой акционной цены. Комбо не участвуют.</div><div class="save-bar"><span class="tiny muted">Со следующего торгового дня</span>${btn('Сохранить акцию','savePromotion','primary small')}</div>`:combo?`<h2>Комбо из готовых блюд</h2>${field('Название','comboName','Комбо с бургером')}${field('Цена набора, ₽','comboPrice','540','number','','min="0"')}<table><thead><tr><th>Блюдо</th><th>Количество</th><th></th></tr></thead><tbody><tr><td>Классический бургер</td><td>1</td><td>×</td></tr><tr><td>Картофель фри</td><td>1</td><td>×</td></tr><tr><td>Лимонад</td><td>1</td><td>×</td></tr></tbody></table><div style="margin-top:18px">${select('Добавить готовое блюдо','comboDish',['Пирожок с вишней','Классический бургер','Лимонад'])}${btn('Добавить в набор','addCombo','small')}</div>${A.comboAdded?'<div class="notice success">В набор добавлен пирожок с вишней · 1 шт.</div>':''}<div class="save-bar"><span class="tiny muted">Без изменения состава блюд</span>${btn('Сохранить комбо','saveEntry','primary small')}</div>`:`<h2>Позиция меню</h2>${field('Название','dishName','Классический бургер')}${select('Категория','dishCategory',['Бургеры','Гарниры','Напитки','Десерты','Комбо'],'Бургеры')}<div class="form-row">${field('Цена, ₽','price','300','number','','min="0" required')}${field('Масса, г','weight','230','number','','min="1" required')}</div><label class="field"><span>Состав для гостя</span><textarea name="composition">Булочка, говяжья котлета, томаты, салат, маринованные огурцы, соус.</textarea></label><div class="field"><span>Аллергены</span><div class="row smalltext"><label><input type="checkbox" checked> Глютен</label><label><input type="checkbox" checked> Молоко</label><label><input type="checkbox" checked> Горчица</label></div></div><span class="tiny muted">Технологическая карта: версия 2</span><div class="save-bar"><span class="tiny muted">Действует с 17 ноября</span>${btn('Сохранить позицию','saveEntry','primary small')}</div>`;return work(title('Меню следующего торгового дня','Текущее меню и оплаченные покупки не изменятся.',pill('17 ноября · черновик'))+`${A.state==='conflict'?'<div style="margin-bottom:18px">'+notice('Меню уже изменено другим сотрудником. Сравните актуальную версию перед сохранением.','error')+'</div>':''}<div class="editor-layout"><section class="table-card"><div class="table-title"><h2>Позиции меню</h2>${btn('+ Позиция','newEntry','small')}</div><table><thead><tr><th>Название</th><th>Категория</th><th>Цена</th></tr></thead><tbody>${[products[0],products[1],pBy('fries'),pBy('drink'),pBy('combo')].map((p,i)=>`<tr class="${i===0&&!combo?'selected-row':''}" data-action="editEntry"><td>${p.name}</td><td>${p.kind==='drink'?'Напитки':p.kind==='fries'?'Гарниры':p.id==='combo'?'Комбо':'Бургеры'}</td><td>${money(p.price)}</td></tr>`).join('')}</tbody></table><div style="padding:22px" class="stack">${btn('Настроить бизнес-ланч','editPromotion','small')}${btn('Редактировать комбо','editCombo','small')}</div></section><section class="panel">${editor}</section></div>`,'Меню следующего дня','assortment',true);}
function recipe(){let isEmpty=A.state==='empty';return work(title('Технологические карты','Изменения применяются со следующего торгового дня.',pill('17 ноября · будущая версия'))+`<div class="recipe-layout"><aside class="table-card dish-list"><div class="table-title"><h2>Блюда</h2></div>${['Классический бургер','Чизбургер','Куриный бургер','Картофель фри'].map((d,i)=>`<button class="${i===0?'selected':''}" data-action="selectRecipe">${d}</button>`).join('')}</aside><section class="panel"><div class="row between"><h2>Классический бургер</h2>${pill(isEmpty?'Карта не создана':'Версия 2')}</div>${isEmpty?empty('У блюда пока нет техкарты','Укажите ингредиенты и согласованные параметры приготовления.'):`${A.state==='validation'?notice('Количество ингредиента должно быть больше нуля. Проверьте строку «Котлета».','error'):''}<h3 style="margin-top:22px">Ингредиенты</h3><table class="recipe-table"><thead><tr><th>Ингредиент</th><th style="width:155px">Количество</th><th style="width:130px">Единица</th></tr></thead><tbody>${[['Булочка','1','шт'],['Котлета',A.state==='validation'?'0':'0.12','кг'],['Соус','0.02','кг']].map(([n,q,u],i)=>`<tr><td><select name="ingredient${i}"><option>${n}</option><option>Листовой салат</option><option>Томат</option></select></td><td><input type="number" name="quantity${i}" value="${q}" min="0" step="any"></td><td>${u}</td></tr>`).join('')}${A.extraIngredient?'<tr><td>Листовой салат</td><td><input type="number" name="quantity3" value="0.015" min="0" step="any"></td><td>кг</td></tr>':''}</tbody></table><div style="margin:18px 0 26px">${btn('+ Ингредиент','addIngredient','small')}</div><h3>Параметры приготовления</h3><div class="form-row">${select('Согласованная программа','recipeProgram',['Стандартная · бургер','Стандартная · курица'])}${field('Обозначение версии','programVersion','2','number','','min="1"')}</div><div class="notice info">Используются программы, согласованные с роботизированным комплексом.</div>`}<div class="save-bar"><span class="tiny muted">${isEmpty?'Без техкарты позиция не допускается к продаже':'Текущая техкарта и начатые заказы сохраняются'}</span>${btn(isEmpty?'Создать карту':'Сохранить новую версию',isEmpty?'createRecipe':'saveRecipe','primary small')}</div></section></div>`,'Технологические карты','technology',true);}
function production(){const stale=A.state==='stale';return work(title('Состояние комплекса','Роботы, технические ошибки и потребность в пополнении.',pill(stale?'Данные устарели · 12:38':'Обновлено 12:40',stale?'amber':'green'))+`${stale?'<div style="margin-bottom:20px">'+notice('Нет свежего подтверждения состояний. Ниже показаны последние полученные данные.','error')+'</div>':''}${A.state==='empty'?'<section class="panel">'+empty('Нет подключенных роботов','Проверьте подключение комплекса во внешнем контуре.')+'</section>':`<div class="three-col"><div class="robot"><h2>Робот 01</h2>${pill('Готов к работе','green')}<p>Ошибок не обнаружено.</p></div><div class="robot"><h2>Робот 02</h2>${pill('Готовит заказ','amber')}<p>Задание выполняется.</p></div><div class="robot"><h2>Робот 03</h2>${pill('Техническая ошибка','red')}<p>Нет подтверждения исправности датчика. Требуется проверка.</p></div></div><section class="table-card" style="margin-top:24px"><div class="table-title"><h2>Полуфабрикаты и пополнение</h2><span class="tiny muted">Пополнение требуется при остатке ниже 30%</span></div><table><thead><tr><th>Робот</th><th>Полуфабрикат</th><th>Остаток</th><th>Уровень</th><th>Оценка окончания</th><th>Состояние</th></tr></thead><tbody>${[['02','Котлеты','2,4 кг',24,'13:05'],['01','Булочки','40 шт',40,'13:40'],['02','Соус','0,8 л',16,'12:55']].map(([r,n,q,p,t])=>`<tr><td>${r}</td><td>${n}</td><td>${q}</td><td><div class="row"><div class="progress ${p<30?'low':''}"><span style="width:${p}%"></span></div><span>${p}%</span></div></td><td>${stale?'Последняя оценка: ':''}${t}</td><td>${pill(p<30?'Нужно пополнить':'Достаточно',p<30?'amber':'green')}</td></tr>`).join('')}</tbody></table></section><p class="smalltext muted" style="margin-top:24px">Пополнение и устранение технических ошибок выполняются по регламенту производства.</p>`}`,'Состояние комплекса','production',true);}
function report(){const zero=A.state==='empty';const metrics=[['Оплаченных заказов',zero?'0':'47'],['До скидок',zero?'0 ₽':'60 000 ₽'],['Скидки',zero?'0 ₽':'3 500 ₽'],['Оплачено деньгами',zero?'0 ₽':'55 000 ₽'],['Списано бонусов',zero?'0':'1 500'],['Возвраты подтверждены',zero?'0 ₽':'2 000 ₽']];const status={default:['Не передавался',''],exportPending:['Передача выполняется','amber'],exported:['Прием подтвержден','green'],exportError:['Не удалось передать','red'],empty:['Нет операций','']}[A.state]||['Не передавался',''];return work(title('Продажи и возвраты','Денежный итог учитывает только подтвержденные возвраты.')+`<section class="panel"><div class="filter-row">${select('Ресторан','reportRestaurant',['Москва · ресторан 01'])}${field('С','reportFrom','2026-11-15','date')}${field('До, не включая','reportTo','2026-11-16','date')}${btn('Показать отчет','makeReport','primary')}</div></section><div class="metrics">${metrics.map(([l,v])=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="two-col"><section class="panel"><h2>Денежный итог</h2><table class="report-table"><tbody><tr><td>Денежные оплаты</td><td>${zero?'0':'55 000'} ₽</td></tr><tr><td>Подтвержденные возвраты</td><td>−${zero?'0':'2 000'} ₽</td></tr><tr><td><strong>Итого за период</strong></td><td style="font-size:27px">${zero?'0':'53 000'} ₽</td></tr></tbody></table><p class="tiny muted" style="line-height:1.6">Возврат учитывается датой подтверждения. Бонусы показаны отдельно и не включены в денежный итог.</p></section><section class="panel"><div class="row between"><h2 style="margin:0">Передача в 1С</h2>${pill(status[0],status[1])}</div><dl class="info-grid"><div><dt>Торговый день</dt><dd>15 ноября 2026 · закрыт</dd></div><div><dt>Пакет</dt><dd>${A.state==='default'||zero?'Не сформирован':'№ 01-20261115'}</dd></div></dl>${A.state==='exportError'?notice('1С недоступна. Пакет сохранен для повторной передачи. Продажи продолжаются.','error'):A.state==='exported'?notice('Все операции пакета приняты. Повторная передача не создаст повторных продаж.','success'):notice('Передаются операции закрытого дня. Повтор использует исходный пакет.','info')}<div style="margin-top:22px">${btn(A.state==='exportError'?'Повторить передачу':'Передать закрытый день','export','primary wide',zero||A.state==='exportPending'||A.state==='exported')}</div></section></div>`,'Продажи и возвраты','analyst',true);}
function dialog(){let type=A.modal||((A.screen==='K-03'&&A.state==='type')?'service':(A.screen==='K-01'&&A.state==='idle')?'idle':(A.screen==='S-04'&&A.state==='stop')?'stop':(A.screen==='S-02'&&A.state==='verify')?'verify':(A.screen==='S-02'&&A.state==='cancel')?'impossibility':(A.screen==='S-02'&&A.state==='refund')?'externalRefund':(A.screen==='R-03'&&A.state==='cancel')?'cashCancel':(A.screen==='R-04'&&A.state==='cancel')?'r1Cancel':(A.screen==='R-04'&&A.state==='refund')?'r1Refund':(A.screen==='R-02'&&A.state==='method')?'method':null);if(!type)return '';let body='',buttons='';if(type==='method'){body='<h2>Выберите способ оплаты</h2><p>К оплате '+money(A.snapshotAmount??(1790-A.bonus))+'.</p><div class="service-options"><button class="service-option" data-action="methodCard">Банковская карта</button><button class="service-option" data-action="methodCash">Наличные</button></div>';buttons=btn('Назад','closeModal');}else if(type==='service'){body='<h2>Где будете есть?</h2><p>Выбор влияет на упаковку вашего заказа.</p><div class="service-options"><button class="service-option" data-action="chooseService:dine_in"><div class="service-icon">◯</div>В зале</button><button class="service-option" data-action="chooseService:takeaway"><div class="service-icon">▱</div>С собой</button></div>';buttons=btn('Вернуться к заказу','closeModal');}else if(type==='help'){body='<h2>Как получить помощь</h2><p>Обратитесь к менеджеру в зале. Если заказ уже оплачен, сообщите его номер и покажите подтверждение оплаты.</p>';buttons=btn('Понятно','closeModal','primary');}else if(type==='idle'){body='<h2>Вы еще выбираете?</h2><p>Вы не пользовались киоском 2 минуты. Еще через 2 минуты корзина будет очищена.</p>';buttons=btn('Начать заново','reset')+btn('Продолжить','continueSession','primary');}else if(type==='verify'){body='<h2>Проверка покупки 042</h2><p>Сопоставьте подтверждение оплаты с киоском, временем, составом и суммой покупки.</p>'+field('Ссылка на подтверждение оплаты','evidence','BANK-042-01','text','','required')+'<label class="checkbox"><input type="checkbox" name="evidenceChecked" required><span>Подтверждение проверено. Сумма 378 ₽ и данные покупки совпадают.</span></label>';buttons=btn('Отмена','closeModal')+btn('Покупка проверена','confirmVerification','primary');}else if(type==='impossibility'||type==='r1Cancel'){body=`<h2>${type==='r1Cancel'?'Отменить заказ 042?':'Заказ невозможно выполнить?'}</h2><p>${type==='r1Cancel'?'Приготовление еще не началось. Отмена прекратит выполнение; возврат денег учитывается отдельно.':'Будет зафиксировано прекращение выполнения и необходимость полного возврата 378 ₽.'}</p>`+select('Причина','cancelReason',type==='r1Cancel'?['Просьба гостя до приготовления','Невозможность выполнения','Подтвержденная проблема']:['Невозможность выполнения','Подтвержденная проблема'])+'<label class="field"><span>Комментарий</span><textarea name="cancelComment" placeholder="Укажите обстоятельства" required></textarea></label>';buttons=btn('Назад','closeModal')+btn('Подтвердить отмену','confirmCancellation','danger');}else if(type==='externalRefund'){body='<h2>Внешний возврат</h2><p>Возврат 378 ₽ проводится внешними средствами. Укажите идентификатор, чтобы проверить результат.</p>'+select('Провайдер','provider',['Эквайринг ресторана','Кассовый контур'])+field('Идентификатор операции возврата','refundReference','','text','','required');buttons=btn('Отмена','closeModal')+btn('Зарегистрировать для проверки','registerRefund','primary');}else if(type==='r1Refund'){body='<h2>Полный возврат по заказу '+e(A.selectedOrder||'042')+'</h2><div class="sum-row strong"><span>К возврату</span><span>378 ₽</span></div><p>Деньги возвращаются на исходный способ оплаты. Подтверждение возврата и кассовый документ будут проверены отдельно от отмены заказа.</p>';buttons=btn('Назад','closeModal')+btn('Оформить полный возврат','registerRefund','primary');}else if(type==='stop'){body='<h2>Остановить новые продажи?</h2><p>Новые сессии и оплата будут запрещены. Начатые платежи продолжат проверяться, оплаченные заказы останутся в работе.</p>'+field('Причина остановки','stopReason','Технический перерыв','text','','required');buttons=btn('Назад','closeModal')+btn('Остановить продажи','confirmStop','danger');}else if(type==='cashCancel'){body='<h2>Вернуть внесенные деньги?</h2><p>Внесено '+money(A.cash)+'. Дождитесь подтверждения возврата, прежде чем начинать новую оплату.</p>';buttons=btn('Продолжить оплату','closeModal')+btn('Вернуть '+money(A.cash),'confirmCashReturn','primary');}return `<div class="overlay"><section class="dialog" role="dialog" aria-modal="true">${body}<div class="actions">${buttons}</div></section></div>`;}
const renderers={'K-01':catalog,'K-02':dish,'K-03':cart,'K-04':payment,'K-05':paid,'K-06':documentHelp,'K-07':stopped,'B-01':board,'B-02':pickup,'S-00':login,'S-01':problems,'S-02':()=>orderDetail(false),'S-03':cells,'S-04':sales,'R-01':loyalty,'R-02':bonus,'R-03':cash,'R-04':fullManager,'R-05':menuEditor,'R-06':recipe,'R-07':production,'R-08':report};
function currentMeta(){return meta.find(m=>m.id===A.screen)||meta[0];}
function nav(id,state='default'){if(id.includes(':'))[id,state]=id.split(':');A.screen=renderers[id]?id:'K-01';A.state=state;A.modal=null;A.toast='';render();}
function showToast(message){A.toast=message;render();}
function validate(names){for(const name of names){let input=document.querySelector(`#screen [name="${name}"]`);if(input&&!input.reportValidity())return false;}return true;}
function fit(){const m=currentMeta(),w=m.format==='kiosk'?900:1440,h=m.format==='kiosk'?1360:m.format==='board'?900:1000;const screen=document.querySelector('#screen'),wrap=document.querySelector('#frame-wrap');screen.style.width=w+'px';screen.style.height=h+'px';let scale=1;if(!capture){let stage=document.querySelector('#stage'),z=document.querySelector('#zoom').value;scale=z==='fit'?Math.min(1,(stage.clientWidth-48)/w,(stage.clientHeight-48)/h):Number(z);}screen.style.transform=`scale(${scale})`;wrap.style.width=w*scale+'px';wrap.style.height=h*scale+'px';}
function scenarioActions(){if(A.screen==='K-04')return 'Результат терминала: '+btn('Успешная оплата','resultPaid','small')+btn('Подтвержденный отказ','resultDeclined','small')+btn('Ответ не получен','resultUnknown','small');if(A.screen==='K-05')return 'Состояние принтера: '+btn('Документы выданы','printed','small')+btn('Печать не удалась','printFailure','small');if(A.screen==='K-06')return 'Сотрудник: '+btn('Принял проблему; терминал свободен','managerAccepted','small');if(A.screen==='B-02')return 'События комплекса: '+btn('Талон принят','scanValid','small')+btn('Часть осталась','pickupPartial','small')+btn('Полный цикл выдачи подтвержден','pickupDone','small')+btn('Срок истек','pickupExpired','small');if(A.screen==='R-03')return 'События устройства: '+btn('Внесено 100 ₽','insert100','small')+btn('Оплата и сдача подтверждены','cashPaid','small')+btn('Возврат подтвержден','cashReturned','small');if(['S-02','R-04'].includes(A.screen)&&A.state==='refundPending')return 'Внешний контур: '+btn('Возврат денег и чек подтверждены','refundConfirmed','small');if(A.screen==='S-03'&&A.state==='checking')return 'Контроль ячейки: '+btn('Закрыта, исправна, пуста','cellConfirmed','small');if(A.screen==='R-08'&&A.state==='exportPending')return 'Ответ 1С: '+btn('Прием подтвержден','exportConfirmed','small')+btn('Нет ответа','exportFailed','small');return 'Панель демонстрации · переходы и состояния не выполняют реальные операции';}
function render(){const m=currentMeta();if(!m.states[A.state]&& !['cancelled','refundConfirmed'].includes(A.state))A.state='default';document.querySelector('#screen').innerHTML=renderers[A.screen]()+dialog()+(A.toast?`<div class="toast" role="status">${e(A.toast)}</div>`:'');document.querySelector('#screen-title').textContent=m.id+' · '+m.name;document.querySelector('#screen-meta').textContent=m.role+' · '+m.release;document.querySelector('#state-select').innerHTML=Object.entries(m.states).map(([k,v])=>`<option value="${k}" ${k===A.state?'selected':''}>${v}</option>`).join('');document.querySelectorAll('#screen-list button').forEach(b=>b.classList.toggle('active',b.dataset.screen===A.screen));document.querySelector('#scenario-bar').innerHTML=scenarioActions();if(!capture){const u=new URL(location.href);u.searchParams.set('screen',A.screen);u.searchParams.set('state',A.state);history.replaceState({},'',u);}fit();}
function action(name){if(!name)return;if(name.startsWith('r1Detail:')){A.selectedOrder=name.slice(9);nav('R-04','detail');return;}if(name.startsWith('go:')){if(name.slice(3)==='S-00'){A.values={};A.verified=false;}nav(name.slice(3));return;}if(name.startsWith('category:')){A.category=name.slice(9);A.state='default';render();return;}if(name.startsWith('dish:')){A.values.dish=name.slice(5);A.qty=1;nav('K-02');return;}if(name.startsWith('add:')){const id=name.slice(4),line=A.cart.find(l=>l.id===id);if(line)line.qty++;else A.cart.push({id,qty:1});A.snapshotAmount=null;A.toast='Добавлено в корзину';render();return;}if(name.startsWith('plus:')||name.startsWith('minus:')){const [op,id]=name.split(':'),n=op==='plus'?1:-1;if(id==='dish')A.qty=Math.max(1,A.qty+n);else{const l=A.cart.find(l=>l.id===id);if(l)l.qty=Math.max(1,l.qty+n);A.state='default';A.snapshotAmount=null;}render();return;}if(name.startsWith('remove:')){A.cart=A.cart.filter(l=>l.id!==name.slice(7));A.state='default';A.snapshotAmount=null;render();return;}if(name.startsWith('chooseService:')){A.service=name.slice(14);A.state='default';A.modal=null;render();return;}
 switch(name){
 case 'help':help();break;
 case 'reset':A.cart=[];A.values={};A.snapshotAmount=null;A.bonus=300;A.cash=0;A.verified=false;nav('K-01');break;
 case 'continueSession':A.modal=null;A.state='default';render();break;
 case 'closeModal':A.modal=null;if(A.state==='refund'){A.state='cancelled';render();break;}if(A.state==='type'||A.state==='idle'||A.state==='stop'||A.state==='verify'||A.state==='cancel'||A.state==='refund'||A.state==='method')A.state=A.screen==='R-04'?'detail':'default';render();break;
 case 'service':A.modal='service';render();break;
 case 'addDish':{const id=A.values.dish||'classic';const l=A.cart.find(l=>l.id===id);if(l)l.qty+=A.qty;else A.cart.push({id,qty:A.qty});for(const k of ['fries','pie'])if(document.querySelector(`[name="extra-${k}"]`)?.checked){const x=A.cart.find(l=>l.id===k);if(x)x.qty++;else A.cart.push({id:k,qty:1});}A.snapshotAmount=null;nav('K-01');A.toast='Блюдо добавлено в корзину';render();break;}
 case 'prepare':if(!A.cart.length)return;if(!A.service){A.modal='service';render();}else{A.state='confirmed';render();}break;
 case 'pay':if(!['confirmed','changed'].includes(A.state))return;A.snapshotAmount=total(A.state==='changed').amount;nav('K-04');break;
 case 'resultPaid':nav('K-05');break;
 case 'resultDeclined':nav('K-04','declined');break;
 case 'resultUnknown':nav('K-04','unknown');break;
 case 'printed':nav('K-05');break;
 case 'printFailure':nav('K-06');break;
 case 'managerAccepted':nav('K-06','accepted');break;
 case 'scanValid':nav('B-02','open');break;
 case 'pickupPartial':nav('B-02','partial');break;
 case 'pickupDone':nav('B-02','issued');break;
 case 'pickupExpired':nav('B-02','expired');break;
 case 'login':if(validate(['login','password']))nav('S-01');break;
 case 'findMvp':if(!validate(['day','orderNumber']))break;if((A.values.orderNumber||'042')==='042')nav('S-02');else showToast('Заказ не найден. Проверьте торговый день и номер.');break;
 case 'acceptProblem':if(A.state==='accepted')nav('S-02');else{A.state='accepted';render();}break;
 case 'verify':A.modal='verify';render();break;
 case 'confirmVerification':if(!validate(['evidence','evidenceChecked']))break;A.verified=true;A.modal=null;A.state='verified';showToast('Покупка проверена. Повторная печать доступна.');break;
 case 'reprint':if(!A.verified&&A.state!=='verified')return;A.state='reprinted';showToast('Талон 042 напечатан повторно. Номер и код сохранены.');break;
 case 'impossibility':A.modal='impossibility';render();break;
 case 'r1Cancel':A.modal='r1Cancel';render();break;
 case 'confirmCancellation':if(!validate(['cancelComment']))break;A.modal=null;A.state='cancelled';showToast('Выполнение заказа прекращено. Полный возврат требуется.');break;
 case 'externalRefund':A.modal='externalRefund';render();break;
 case 'r1Refund':A.modal='r1Refund';render();break;
 case 'registerRefund':if(document.querySelector('[name="refundReference"]')&&!validate(['refundReference']))break;A.modal=null;A.state='refundPending';showToast('Возврат на проверке. Успех еще не подтвержден.');break;
 case 'refundConfirmed':A.state='refundConfirmed';showToast('Возврат денег и чек возврата подтверждены.');break;
 case 'resolve':if(A.screen==='S-02'&&A.state==='reprinted')A.state='resolved';showToast('Результат разбора сохранен по подтвержденным данным покупки.');break;
 case 'cellDefault':nav('S-03');break;
 case 'cellFault':nav('S-03','fault');break;
 case 'cellAccept':showToast('Задача принята под личной учетной записью.');break;
 case 'cellService':if(A.state==='fault')showToast('Обслуживание отмечено. Неисправность сохраняется, ячейка заблокирована.');else nav('S-03','checking');break;
 case 'cellConfirmed':nav('S-03','empty');A.toast='Ячейка свободна после исправного контроля. Уборка не зарегистрирована как выдача гостю.';render();break;
 case 'stopSales':A.modal='stop';render();break;
 case 'confirmStop':if(!validate(['stopReason']))break;A.modal=null;nav('S-04','stopped');break;
 case 'resumeSales':if(A.state!=='technical'){nav('S-04');showToast('Проверки пройдены. Новые продажи разрешены.');}break;
 case 'authLogin':A.values.authMode='login';nav('R-01');break;
 case 'authRegister':A.values.authMode='register';nav('R-01','register');break;
 case 'sendCode':if(validate(A.state==='register'?['phone','guestName','birthDate','email']:['phone'])){if(A.state==='register')A.values.authMode='register';nav('R-01','code');}break;
 case 'authConfirm':if(validate(['sms']))nav('R-02');break;
 case 'resendCode':showToast('Повторная отправка станет доступна по окончании указанного срока.');break;
 case 'bonusPay':if(!validate(['bonus']))break;A.snapshotAmount=1790-(A.state==='noBonus'?0:A.bonus);A.state='method';render();break;
 case 'methodCard':A.modal=null;nav('K-04');break;
 case 'methodCash':A.modal=null;A.cash=0;nav('R-03');break;
 case 'cancelCash':A.modal='cashCancel';render();break;
 case 'confirmCashReturn':A.modal=null;nav('R-03','returnUnknown');break;
 case 'insert100':if(!['returnUnknown','unavailable'].includes(A.state)){A.cash+=100;render();}break;
 case 'cashPaid':if(A.cash>=dueAmount()&&!['returnUnknown','unavailable'].includes(A.state))nav('K-05');else showToast('Для подтверждения полной оплаты внесите оставшуюся сумму.');break;
 case 'cashReturned':if(A.state==='returnUnknown'){A.cash=0;nav('K-03');showToast('Возврат внесенных денег подтвержден. Проверьте заказ перед новой попыткой.');}break;
 case 'r1Detail':A.selectedOrder='042';nav('R-04','detail');break;
 case 'searchOrders':if(validateDateRange('dateFrom','dateTo'))render();break;
 case 'editEntry':nav('R-05');break;
 case 'newEntry':A.values.dishName='';A.values.price='';A.values.weight='';nav('R-05');break;
 case 'editPromotion':nav('R-05','promotion');break;
 case 'editCombo':nav('R-05','combo');break;
 case 'saveEntry':if(validate(['dishName','price','weight','comboName','comboPrice']))showToast('Будущая версия сохранена. Изменения действуют со следующего торгового дня.');break;
 case 'savePromotion':if(validate(['promoName','discount','startTime','endTime']))showToast('Условия акции сохранены для следующего торгового дня.');break;
 case 'addCombo':A.comboAdded=true;showToast('Блюдо добавлено в состав комбо.');break;
 case 'selectRecipe':nav('R-06');break;
 case 'createRecipe':nav('R-06');break;
 case 'addIngredient':A.extraIngredient=true;render();break;
 case 'saveRecipe':if([...document.querySelectorAll('[name^="quantity"]')].some(i=>Number(i.value)<=0)){A.state='validation';render();break;}if(validate(['quantity0','quantity1','quantity2','quantity3']))showToast('Новая версия техкарты сохранена. Начнет действовать со следующего торгового дня.');break;
 case 'makeReport':if(validateDateRange('reportFrom','reportTo'))showToast('Отчет за выбранный период сформирован.');break;
 case 'export':nav('R-08','exportPending');break;
 case 'exportConfirmed':nav('R-08','exported');break;
 case 'exportFailed':nav('R-08','exportError');break;
 }
}
function dueAmount(){return A.snapshotAmount??total().amount;}
function validateDateRange(from,to){const f=A.values[from]||document.querySelector(`[name="${from}"]`)?.value,t=A.values[to]||document.querySelector(`[name="${to}"]`)?.value;if(f>=t){showToast('Дата начала должна быть раньше даты окончания.');return false;}return true;}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target&&!target.disabled)action(target.dataset.action);const screenLink=event.target.closest('[data-screen]');if(screenLink)nav(screenLink.dataset.screen);});
document.addEventListener('input',event=>{if(event.target.name&&event.target.type!=='checkbox')A.values[event.target.name]=event.target.value;});
document.addEventListener('change',event=>{if(event.target.name)A.values[event.target.name]=event.target.type==='checkbox'?event.target.checked:event.target.value;if(event.target.name==='bonus'){const n=Number(event.target.value);if(Number.isInteger(n)&&n>=0&&n<=537){A.bonus=n;render();}else event.target.reportValidity();}});
document.querySelector('#state-select').addEventListener('change',event=>{A.state=event.target.value;A.modal=null;A.toast='';render();});
document.querySelector('#zoom').addEventListener('change',fit);window.addEventListener('resize',fit);
let group='';document.querySelector('#screen-list').innerHTML=meta.map(m=>{let h=m.group!==group?`<h3>${m.group}</h3>`:'';group=m.group;return h+`<button data-screen="${m.id}">${m.id} · ${m.name}</button>`;}).join('');
if(location.protocol==='file:')document.querySelector('.doc-link').href='../../05_api/ui.md';
if(capture)document.body.classList.add('capture');
globalThis.prototypeApp={nav,render,state:A,action,meta};
render();
